languages.javascript:
const value = text.trim();
if (!/^[+-]?[0-9]+$/.test(value)) throw new Error('Not an integer: "' + text + '"');
const result = Number(value);
if (!Number.isSafeInteger(result)) throw new Error('Integer out of range: "' + text + '"');
return result;

